(()=>{'use strict';const $=id=>document.getElementById(id),key='zuxuru-fashion-growth-v1';let s={partners:[],prospects:[],metrics:[]};const valid=v=>v&&['partners','prospects','metrics'].every(k=>Array.isArray(v[k])&&v[k].length<=500&&v[k].every(x=>x&&typeof x==='object'&&typeof x.id==='string'));try{const v=JSON.parse(localStorage.getItem(key));if(valid(v))s=v;}catch{}const el=(t,text)=>{const n=document.createElement(t);if(text!==undefined)n.textContent=text;return n;};function url(v){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return '';}}
function save(){try{localStorage.setItem(key,JSON.stringify(s));$('growth-status').textContent='Saved in this browser.';}catch{$('growth-status').textContent='Could not save. Export your growth backup.';}}
const dashboard='https://bonga-bhengu.donlegendwear.chatgpt.site/fashion-service.html';$('install-link').value=dashboard;$('install-code').value='<a href="'+dashboard+'" target="_blank" rel="noopener noreferrer">For designers</a>';
for(const [button,field] of [['copy-install-link','install-link'],['copy-install-code','install-code']])$(button).onclick=async()=>{try{await navigator.clipboard.writeText($(field).value);$('install-status').textContent='Copied.';}catch{$(field).focus();$(field).select();$('install-status').textContent='Select and copy the text above.';}};
function render(){for(const k of ['partners','prospects','metrics']){const box=$('fashion-'+k);box.replaceChildren();if(!s[k].length)box.append(el('p','No records saved yet. Add actual information above.'));s[k].forEach(r=>{const card=el('article');card.className='record';card.append(el('h3',r.name||r.period));if(k==='partners')card.append(el('p',r.type+' · '+r.stage),el('p','Quote: '+(r.quote||'Unknown')+' · Minimum order: '+(r.moq||'Unknown')),el('p','Lead time / delivery: '+(r.leadtime||'Unknown')),el('p',r.contact),el('p',r.notes));if(k==='prospects'){card.append(el('p',r.stage),el('p',r.need),el('p',r.evidence),el('p','Next: '+(r.next||'Not recorded')));const offer=el('button','Prepare personalised offer');offer.onclick=()=>{$('fashion-offer').hidden=false;$('fashion-offer').value=`Hello ${r.name},\nBased on your recorded request: ${r.need}\nI can propose a design consultation, fabric selection, approved sample and production package.\nTo prepare a final quote, please confirm measurements, quantity, budget and required date.\nFabric, manufacturing, packaging and delivery costs require confirmation.\nNext step: ${r.next||'Discuss your brief.'}\nDraft for review — not sent.`;};card.append(offer);const followLabel=el('label','Next follow-up action'),follow=el('textarea');follow.value=r.next||'';follow.maxLength=1000;follow.onchange=()=>{r.next=follow.value.trim();save();};followLabel.append(follow);card.append(followLabel);const handoff=el('button','Review as customer enquiry');handoff.type='button';handoff.onclick=()=>{const f=$('order-form');if(!f)return;let orders=[];try{orders=JSON.parse(localStorage.getItem('zuxuru-fashion-service-v1'))?.orders||[];}catch{}if(orders.some(o=>o.customer===r.name&&o.request===String(r.need||'').slice(0,300))){$('growth-status').textContent='A matching enquiry is already saved. Review it in Sales & delivery.';location.hash='orders';return;}if(['customer','request','next','due'].some(k=>f.elements[k].value)&&!confirm('Replace the unsaved enquiry form with this prospect?'))return;f.elements.customer.value=String(r.name||'').slice(0,150);f.elements.request.value=String(r.need||'').slice(0,300);f.elements.next.value=String(r.next||'Confirm the brief, budget, measurements and required date.').slice(0,1000);f.elements.due.value='';$('growth-status').textContent='Prospect copied to the enquiry form for review. Choose Add enquiry to save it; no message has been sent.';location.hash='orders';f.elements.customer.focus();};card.append(handoff);} 
if(k==='metrics'){const known=n=>Number.isFinite(r[n]);card.append(el('p',`Visits: ${known('visits')?r.visits:'Unknown'} · Enquiries: ${known('enquiries')?r.enquiries:'Unknown'} · Sales: ${known('sales')?r.sales:'Unknown'}`));card.append(el('p',known('sales')&&known('enquiries')&&r.enquiries>0?'Enquiry-to-sale conversion: '+(r.sales/r.enquiries*100).toFixed(1)+'%':'Conversion unknown — needs confirmed sales and nonzero enquiries.'));card.append(el('p',known('revenue')&&known('spend')&&r.spend>0?'Recorded revenue / campaign spend: '+(r.revenue/r.spend).toFixed(2)+'× (not profit or proof of attribution)':'Campaign return unknown.'));card.append(el('p',r.notes));}
if(k==='partners'&&['Fabric','Manufacturer','White-label','Dropshipping','Packaging'].includes(r.type)){const use=el('button','Use in garment plan');use.type='button';use.onclick=()=>{const f=$('product-form'),field=r.type==='Fabric'?'fabricURL':r.type==='Packaging'?'packaging':'makerURL',idField=r.type==='Fabric'?'fabricPartnerId':r.type==='Packaging'?'packagingPartnerId':'makerPartnerId',value=r.type==='Packaging'?String(r.name||''):url(r.url);if(!value){$('growth-status').textContent='Add a valid public source URL to this supplier before using it in a garment plan.';return;}if(f.elements[field].value&&f.elements[field].value!==value&&!confirm('Replace the current sourcing selection in your garment form?'))return;f.elements[field].value=value;f.elements[idField].value=r.id;const details=f.querySelector('details');if(details)details.open=true;$('garment-sourcing-note').textContent='Sourcing selection for review: '+r.name+' · '+r.stage+' · Quote: '+(r.quote||'Unknown')+' · Minimum order: '+(r.moq||'Unknown')+' · Lead time: '+(r.leadtime||'Unknown')+'. Confirm unit costs separately. Save the product to keep this selection.';location.hash='catalogue';f.elements[field].focus();};card.append(use);}const u=url(r.url);if(u){const a=el('a','Open source');a.href=u;a.target='_blank';a.rel='noopener noreferrer';card.append(a);}if(k!=='metrics'){const label=el('label','Update status'),select=el('select');const form=$(k==='partners'?'fashion-partner-form':'fashion-prospect-form');for(const o of form.elements.stage.options)select.append(new Option(o.text,o.value));select.value=r.stage;select.onchange=()=>{r.stage=select.value;save();render();};label.append(select);card.append(label);const edit=el('button',k==='partners'?'Edit supplier details':'Edit prospect details');edit.type='button';edit.onclick=()=>{if(form.dataset.dirty==='true'&&!confirm('Replace your unsaved form changes with this record?'))return;form.reset();for(const [field,value] of Object.entries(r)){if(form.elements[field])form.elements[field].value=value??'';}form.dataset.editId=r.id;form.dataset.dirty='false';form.querySelector('button').textContent='Save record changes';form.querySelector('[data-cancel-edit]').hidden=false;location.hash=k==='partners'?'partners':'prospects';form.elements.name.focus();};card.append(edit);}const remove=el('button','Remove');remove.onclick=()=>{if(confirm('Remove this record?')){s[k]=s[k].filter(x=>x.id!==r.id);save();render();}};card.append(remove);box.append(card);});}}
for(const [id,k] of [['fashion-partner-form','partners'],['fashion-prospect-form','prospects'],['fashion-metrics-form','metrics']]){const form=$(id),submit=form.querySelector('button'),initialLabel=submit.textContent,cancel=el('button','Cancel editing');cancel.type='button';cancel.hidden=true;cancel.dataset.cancelEdit='true';form.append(cancel);form.addEventListener('input',()=>{form.dataset.dirty='true';});form.addEventListener('reset',()=>{delete form.dataset.editId;form.dataset.dirty='false';submit.textContent=initialLabel;cancel.hidden=true;});cancel.onclick=()=>{if(form.dataset.dirty==='true'&&!confirm('Discard unsaved changes to this form?'))return;form.reset();};form.onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target)),editId=form.dataset.editId,index=editId?s[k].findIndex(r=>r.id===editId):-1;if(editId&&index<0){$('growth-status').textContent='This record was removed. Cancel editing before adding a new record.';return;}v.id=editId||crypto.randomUUID();if(v.url)v.url=url(v.url);if(k==='metrics')for(const n of ['visits','enquiries','sales','revenue','spend'])v[n]=v[n]===''?null:Number(v[n]);if(index>=0)s[k][index]={...s[k][index],...v};else s[k].push(v);save();render();form.reset();};}
$('product-form').addEventListener('reset',()=>{if($('garment-sourcing-note'))$('garment-sourcing-note').textContent='';});
$('growth-backup').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify({format:key,...s},null,2)],{type:'application/json'}));const a=el('a');a.href=u;a.download='zuxuru-fashion-growth.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};$('growth-restore').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error();const v=JSON.parse(await f.text());if(v.format!==key||!valid(v))throw Error();if(!confirm('Replace partners, prospects and growth records with this backup?'))return;s={partners:v.partners,prospects:v.prospects,metrics:v.metrics};save();render();}catch{$('growth-status').textContent='Invalid growth backup. Nothing restored.';}e.target.value='';};render();})();
